<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
const settings=ref([]),purposes=ref([]),banks=ref([]),loading=ref(true),success=ref(null),error=ref(''),qrOpen=ref(false),receiptCopied=ref(false)
const route=useRoute()
const form=reactive({donor_name:'',mobile:'',amount:'',donation_purpose_id:'',payment_method:'bkash',bank_account_id:'',transaction_id:'',payment_screenshot:null,note:''})
const activeSetting=computed(()=>settings.value.find(s=>s.method===form.payment_method))
onMounted(async()=>{try{const[s,p]=await Promise.all([fetch('/api/donation-settings').then(r=>r.json()),fetch('/api/donation-purposes').then(r=>r.json())]);settings.value=s.payment_settings;banks.value=s.bank_accounts;purposes.value=p;if(route.query.event_title)form.note=`${route.query.event_title} অনুষ্ঠানের জন্য দান`}finally{loading.value=false}})
async function submit(){error.value='';const data=new FormData;Object.entries(form).forEach(([k,v])=>{if(v!==null&&v!=='')data.append(k,v)});const r=await fetch('/api/donations',{method:'POST',body:data,headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok){error.value=Object.values(j.errors||{}).flat()[0]||'তথ্য জমা দেওয়া যায়নি।';return}receiptCopied.value=false;success.value=j.donation}
async function copyNumber(){if(activeSetting.value?.number)await navigator.clipboard.writeText(activeSetting.value.number)}
async function copyReceipt(){if(success.value?.receipt_number){await navigator.clipboard.writeText(success.value.receipt_number);receiptCopied.value=true}}
</script>
<template><section class="page-intro"><p class="eyebrow">🙏 দান করুন</p><h1>আপনার সহমর্মী দান</h1><p>আপনার মূল্যবান দান বিহারের ধর্মীয়, সামাজিক, শিক্ষামূলক ও সেবামূলক কার্যক্রমে সহায়তা করবে।</p></section><section v-if="success" class="form-wrap"><div class="success"><i>✓</i><h2>আপনার দানের তথ্য সফলভাবে জমা হয়েছে।</h2><p>আপনার পেমেন্ট যাচাই করা হচ্ছে। যাচাই সম্পন্ন হলে আপনার অনলাইন দানের রসিদ পাওয়া যাবে।</p><div class="receipt-reminder"><div class="receipt-reminder-head"><span>▣</span><div><b>রসিদ নম্বরটি কপি করে রাখুন</b><small>পরে দানের অবস্থা ও রসিদ দেখতে এটি প্রয়োজন হবে</small></div></div><div class="receipt-copy-row"><code>{{success.receipt_number}}</code><button type="button" :class="{ copied: receiptCopied }" @click="copyReceipt"><span>{{receiptCopied?'✓':'⧉'}}</span>{{receiptCopied?'কপি হয়েছে':'কপি করুন'}}</button></div></div><dl><dt>মোবাইল নম্বর</dt><dd>{{success.mobile}}</dd><dt>পরিমাণ</dt><dd>৳ {{success.amount}}</dd><dt>অবস্থা</dt><dd>যাচাই করা হচ্ছে</dd></dl><RouterLink to="/donation-status" class="button primary">দানের অবস্থা দেখুন</RouterLink></div></section><section v-else class="form-wrap"><div v-if="loading" class="loading">তথ্য লোড হচ্ছে…</div><form v-else @submit.prevent="submit"><div class="method-tabs"><button v-for="method in ['bkash','nagad','bank']" :key="method" type="button" :class="{selected:form.payment_method===method}" @click="form.payment_method=method;qrOpen=false">{{method==='bkash'?'বিকাশ':method==='nagad'?'নগদ':'ব্যাংক'}}</button></div><div class="payment-card"><template v-if="form.payment_method==='bank'"><label>ব্যাংক নির্বাচন করুন<select v-model="form.bank_account_id" required><option value="">একটি ব্যাংক বেছে নিন</option><option v-for="bank in banks" :key="bank.id" :value="bank.id">{{bank.bank_name}} — {{bank.account_name}}</option></select></label></template><template v-else-if="activeSetting"><div class="public-payment-info"><div><b>{{form.payment_method==='bkash'?'bKash':'Nagad'}} পেমেন্ট</b><p>নম্বর: <strong>{{activeSetting.number}}</strong></p><p v-if="activeSetting.account_type">অ্যাকাউন্ট: {{activeSetting.account_type}}</p><p v-if="activeSetting.instructions">{{activeSetting.instructions}}</p><button type="button" class="copy-payment" @click="copyNumber">নম্বর কপি করুন</button></div><button v-if="activeSetting.qr_code_url" type="button" class="public-qr" @click="qrOpen=true"><img :src="activeSetting.qr_code_url" :alt="`${activeSetting.method} QR code`"><small>বড় করে দেখুন</small></button></div></template><p v-else>এই পেমেন্ট পদ্ধতি বর্তমানে সক্রিয় নেই।</p></div><h2>দানের তথ্য</h2><div class="form-grid"><label>দাতার নাম<input v-model="form.donor_name" required></label><label>মোবাইল নম্বর<input v-model="form.mobile" placeholder="01XXXXXXXXX" required></label><label>দানের পরিমাণ (৳)<input v-model="form.amount" type="number" min="1" required></label><label>দানের উদ্দেশ্য<select v-model="form.donation_purpose_id" required><option value="">নির্বাচন করুন</option><option v-for="purpose in purposes" :key="purpose.id" :value="purpose.id">{{purpose.name_bn}}</option></select></label><label v-if="form.payment_method!=='bank'">লেনদেনের আইডি<input v-model="form.transaction_id" required></label><label>পেমেন্টের প্রমাণ <small v-if="form.payment_method==='bank'">(আবশ্যক)</small><input type="file" accept="image/jpeg,image/png,image/webp" @change="form.payment_screenshot=$event.target.files[0]" :required="form.payment_method==='bank'"></label></div><label>মন্তব্য (ঐচ্ছিক)<textarea v-model="form.note" rows="3"></textarea></label><p v-if="error" class="error">{{error}}</p><button class="button primary submit">আমি দান করেছি</button></form></section><div v-if="qrOpen&&activeSetting?.qr_code_url" class="qr-modal" role="dialog" aria-modal="true" @click.self="qrOpen=false"><div><button type="button" aria-label="বন্ধ করুন" @click="qrOpen=false">✕</button><h2>{{activeSetting.method==='bkash'?'bKash':'Nagad'}} QR কোড</h2><img :src="activeSetting.qr_code_url" alt="Payment QR code"><p>QR কোড স্ক্যান করে পেমেন্ট করুন</p></div></div></template>

<style scoped>.receipt-reminder{margin:22px 0;padding:17px;border:1px solid #ead39d;border-radius:12px;background:linear-gradient(135deg,#fff9e9,#fffdf5);text-align:left;box-shadow:0 8px 20px #8e68100d}.receipt-reminder-head{display:flex;align-items:center;gap:10px}.receipt-reminder-head>span{display:grid;width:34px;height:34px;place-items:center;border-radius:9px;background:#f0dba8;color:#895f1a;font-size:17px}.receipt-reminder b,.receipt-reminder small{display:block}.receipt-reminder b{color:#634514;font-family:'Noto Serif Bengali',serif;font-size:15px}.receipt-reminder small{margin-top:3px;color:#84765a;font-size:11px;line-height:1.5}.receipt-copy-row{display:flex;align-items:stretch;gap:9px;margin-top:15px}.receipt-copy-row code{display:flex;min-width:0;flex:1;align-items:center;padding:11px 12px;border:1px dashed #d6ba75;border-radius:8px;background:#fff;color:#234f3c;font-family:ui-monospace,monospace;font-size:15px;font-weight:700;letter-spacing:.03em}.receipt-copy-row button{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:0 14px;border:0;border-radius:8px;background:#2c634b;color:#fff;font:inherit;font-size:12px;font-weight:700;cursor:pointer;box-shadow:0 5px 12px #1e523028;transition:.15s}.receipt-copy-row button:hover{background:#204e3a;transform:translateY(-1px)}.receipt-copy-row button span{font-size:17px}.receipt-copy-row button.copied{background:#43875b}@media(max-width:520px){.receipt-copy-row{flex-direction:column}.receipt-copy-row button{min-height:43px}}</style>
